import java.util.*;
import java.io.*;

public class MinCostFlow {
    static final int MAXNODES = 5500;
    static final long INF = 1000000007L;

    static int n, m, k, c, d;
    static int u, v;
    static int flow_total = 0;
    static int s = MAXNODES - 2;
    static int t = MAXNODES - 1;
    static int[] parent = new int[MAXNODES];
    static long total_cost = 0;
    static long[] dist = new long[MAXNODES];

    static class Edge {
        int v, c, idx, cap;
        public Edge(int v, int c, int idx, int cap) {
            this.v = v;
            this.c = c;
            this.idx = idx;
            this.cap = cap;
        }
    }

    static List<Edge>[] adj = new ArrayList[MAXNODES];

    static {
        for (int i = 0; i < MAXNODES; i++) {
            adj[i] = new ArrayList<>();
        }
    }

    static void addEdge(int u, int v, int cost, int capacity) {
        int szU = adj[u].size();
        int szV = adj[v].size();
        adj[u].add(new Edge(v, cost, szV, capacity));
        adj[v].add(new Edge(u, -cost, szU, 0));
    }

    static void findMinCostPath() {
        Arrays.fill(dist, INF);
        PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
        dist[s] = 0;
        pq.offer(new long[]{0, s});
        while (!pq.isEmpty()) {
            long[] curr = pq.poll();
            long currDist = curr[0];
            int node = (int) curr[1];
            if (currDist > dist[node]) continue;
            for (int i = 0; i < adj[node].size(); i++) {
                Edge edge = adj[node].get(i);
                if (edge.cap > 0 && dist[edge.v] > currDist + edge.c) {
                    parent[edge.v] = i;
                    dist[edge.v] = currDist + edge.c;
                    pq.offer(new long[]{dist[edge.v], edge.v});
                }
            }
        }
    }

    static void augmentFlow() {
        int flowInc = k;
        int v = t;
        while (v != s) {
            int u = adj[v].get(parent[v]).v;
            int ind = parent[v];
            flowInc = Math.min(flowInc, adj[u].get(ind).cap);
            v = u;
        }
        flow_total += flowInc;
        total_cost += (long) flowInc * dist[t];
        v = t;
        while (v != s) {
            int u = adj[v].get(parent[v]).v;
            int ind = parent[v];
            adj[v].get(ind).cap += flowInc;
            // Find corresponding reverse edge
            for (Edge e : adj[u]) {
                if (e.v == v && e.idx == adj[u].indexOf(e)) {
                    e.cap -= flowInc;
                    break;
                }
            }
            v = u;
        }
    }

    static int nodeID(int u, int t) {
        return u + t * n;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        m = Integer.parseInt(st.nextToken());
        k = Integer.parseInt(st.nextToken());
        c = Integer.parseInt(st.nextToken());
        d = Integer.parseInt(st.nextToken());

        for (int i = 0; i < MAXNODES; i++) {
            adj[i] = new ArrayList<>();
        }

        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < k; i++) {
            u = Integer.parseInt(st.nextToken());
            addEdge(s, nodeID(u, 0), 0, 1);
        }

        for (int i = 0; i <= n + k; i++) {
            addEdge(nodeID(1, i), t, c * i, k);
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j < n + k; j++) {
                addEdge(nodeID(i, j), nodeID(i, j + 1), 0, k);
            }
        }

        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(br.readLine());
            u = Integer.parseInt(st.nextToken());
            v = Integer.parseInt(st.nextToken());
            for (int j = 0; j < k; j++) {
                for (int l = 0; l < n + k; l++) {
                    addEdge(nodeID(u, l), nodeID(v, l + 1), d * (2 * j + 1), 1);
                    addEdge(nodeID(v, l), nodeID(u, l + 1), d * (2 * j + 1), 1);
                }
            }
        }

        while (flow_total < k) {
            findMinCostPath();
            augmentFlow();
        }

        System.out.println(total_cost);
    }
}
